<span class="line"><span style="color:#C678DD;">    public</span><span style="color:#C678DD;"> long</span><span style="color:#61AFEF;"> GcdRecursive</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">long</span><span style="color:#E5C07B;"> a</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">long</span><span style="color:#E5C07B;"> b</span><span style="color:#ABB2BF;">)</span></span>
